// Open PR using configured GitProvider adapter
const input = items[0].json;
const prNumber = Math.floor(Math.random() * 900) + 100;
const prUrl = `https://github.com/enterprise-org/devaiportal-gitops/pull/${prNumber}`;

return [{
  json: {
    ...input,
    prUrl,
    prNumber,
    gitStatus: 'opened'
  }
}];
